SELECT 
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND batch_number = #{batchNumber}
ORDER BY create_time DESC

SELECT 
FROM  ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND dispatch_record = #{dispatchRecord}
ORDER BY batch_number,dispatch_sum DESC
